const isObj = (value) => value && typeof value === "object" && !Array.isArray(value);
const toArray = (value) => (Array.isArray(value) ? value : []);
const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim();
  return normalized ? normalized : null;
};
const toInt = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : null;
};
const normPhone = (value) => {
  const digits = String(value || "").replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length === 10) return `7${digits}`;
  if (digits.length === 11 && digits.startsWith("8")) return `7${digits.slice(1)}`;
  return digits;
};
const uniq = (values) => Array.from(new Set(values.filter(Boolean)));

function buildSenderName(sender) {
  const firstName = toStr(sender?.first_name || sender?.firstName);
  const lastName = toStr(sender?.last_name || sender?.lastName);
  const fullName = [firstName, lastName].filter(Boolean).join(" ").trim();
  return fullName || toStr(sender?.name) || toStr(sender?.username) || null;
}

function makeHttpResponse(baseMsg, statusCode, payload) {
  return Object.assign({}, baseMsg, {
    statusCode,
    headers: { "Content-Type": "application/json; charset=utf-8" },
    payload,
  });
}

function extractContact(rawMessage, body, attachments) {
  const directContact =
    (isObj(body.contact) ? body.contact : null)
    || (isObj(rawMessage.contact) ? rawMessage.contact : null)
    || attachments.find((item) => isObj(item.contact))?.contact
    || attachments.find((item) => String(item.type || "").toLowerCase() === "contact")
    || null;

  if (!isObj(directContact)) {
    return null;
  }

  const phone =
    normPhone(
      directContact.phone_number
      || directContact.phone
      || directContact.phoneNumber
      || directContact.msisdn,
    );

  if (!phone) return null;

  return {
    phone,
    firstName: toStr(directContact.first_name || directContact.firstName),
    lastName: toStr(directContact.last_name || directContact.lastName),
    userId: toStr(directContact.user_id || directContact.userId),
    raw: directContact,
  };
}

function extractButtonValue(rawMessage, body) {
  return (
    toStr(body.callback_data)
    || toStr(body.callbackData)
    || toStr(body.button)
    || toStr(rawMessage.callback_data)
    || toStr(rawMessage.callbackData)
    || null
  );
}

const stationMap = new Map([
  ["нaгатинская", { id: "nagat", name: "Нагатинская" }],
  ["нагатинская", { id: "nagat", name: "Нагатинская" }],
  ["нагатинская премиум", { id: "nagat_p", name: "Нагатинская Премиум" }],
  ["терехово", { id: "tereh", name: "Терехово" }],
  ["сколково", { id: "kuncev", name: "Сколково" }],
  ["ясенево", { id: "yas", name: "Ясенево" }],
  ["селигерская", { id: "seleger", name: "Селигерская" }],
  ["сочи", { id: "sochi", name: "Сочи" }],
  ["точка сбора", { id: "t-sbora", name: "Точка сбора" }],
  ["nagat", { id: "nagat", name: "Нагатинская" }],
  ["nagat_p", { id: "nagat_p", name: "Нагатинская Премиум" }],
  ["tereh", { id: "tereh", name: "Терехово" }],
  ["kuncev", { id: "kuncev", name: "Сколково" }],
  ["yas", { id: "yas", name: "Ясенево" }],
  ["seleger", { id: "seleger", name: "Селигерская" }],
  ["sochi", { id: "sochi", name: "Сочи" }],
  ["t-sbora", { id: "t-sbora", name: "Точка сбора" }],
]);

function extractStation(text, buttonValue) {
  const candidates = [
    toStr(buttonValue)?.toLowerCase(),
    toStr(text)?.toLowerCase(),
  ].filter(Boolean);

  for (const candidate of candidates) {
    if (stationMap.has(candidate)) {
      return stationMap.get(candidate);
    }
  }
  return null;
}

const expectedSecret = (() => {
  try {
    return toStr(env.get("MAX_BOT_WEBHOOK_SECRET"));
  } catch {
    return null;
  }
})();

const rawPayload = isObj(msg.maxUpdate)
  ? msg.maxUpdate
  : (isObj(msg.payload) ? msg.payload : null);

if (!rawPayload) {
  const response = makeHttpResponse(msg, 400, {
    ok: false,
    provider: "max",
    error: "JSON body is required",
  });
  return [null, response, response];
}

const isWebhook = Boolean(msg.req);
if (isWebhook) {
  const incomingSecret = toStr(msg.req?.headers?.["x-max-bot-api-secret"]);
  if (expectedSecret && incomingSecret !== expectedSecret) {
    const response = makeHttpResponse(msg, 401, {
      ok: false,
      provider: "max",
      error: "Invalid X-Max-Bot-Api-Secret header",
    });
    return [null, response, response];
  }
}

const rawMessage =
  (isObj(rawPayload.message) ? rawPayload.message : null)
  || (isObj(rawPayload.originalMessage) ? rawPayload.originalMessage : null)
  || rawPayload;
const sender = isObj(rawMessage.sender) ? rawMessage.sender : (isObj(rawMessage.from) ? rawMessage.from : {});
const recipient = isObj(rawMessage.recipient) ? rawMessage.recipient : {};
const body = isObj(rawMessage.body) ? rawMessage.body : (isObj(rawPayload.body) ? rawPayload.body : rawMessage);
const attachments = uniq([
  ...toArray(body.attachments),
  ...toArray(rawMessage.attachments),
]).filter((item) => item !== null && item !== undefined);

const text =
  toStr(body.text)
  || toStr(rawMessage.text)
  || toStr(rawPayload.text)
  || toStr(rawPayload.content)
  || null;
const buttonValue = extractButtonValue(rawMessage, body);
const command = text && text.startsWith("/") ? text.split(/\s+/)[0] : null;
const contact = extractContact(rawMessage, body, attachments);
const station = extractStation(text, buttonValue);
const updateType = toStr(rawPayload.update_type || rawPayload.type || rawMessage.type) || "message";
const updateTimestamp = toInt(rawPayload.timestamp || rawMessage.timestamp) ?? Date.now();

const normalized = {
  provider: "max",
  updateType,
  timestamp: updateTimestamp,
  messageId: toStr(rawMessage.mid || rawMessage.message_id || body.mid || body.message_id || rawPayload.messageId),
  messageTimestamp: toInt(rawMessage.timestamp || body.timestamp) ?? updateTimestamp,
  text,
  command,
  buttonValue,
  contact,
  station,
  messageKind: contact
    ? "contact"
    : station
      ? "station"
      : command
        ? "command"
        : (text ? "text" : "unknown"),
  attachments,
  sender: {
    userId: toStr(sender.user_id || sender.userId || sender.id),
    username: toStr(sender.username),
    name: buildSenderName(sender),
    isBot: typeof sender.is_bot === "boolean" ? sender.is_bot : null,
  },
  recipient: {
    chatId: toStr(recipient.chat_id || recipient.chatId || rawPayload.chatId || rawMessage.chatId),
    userId: toStr(recipient.user_id || recipient.userId),
    chatType: toStr(recipient.chat_type || recipient.type || rawPayload.chatType),
  },
  raw: rawPayload,
};

const downstreamMsg = Object.assign({}, msg, {
  topic: `max/${normalized.messageKind}`,
  maxRaw: rawPayload,
  maxUpdate: normalized,
  payload: normalized,
});

const httpResponse = isWebhook
  ? makeHttpResponse(msg, 200, {
      ok: true,
      provider: "max",
      accepted: true,
      messageId: normalized.messageId,
      chatId: normalized.recipient.chatId,
      userId: normalized.sender.userId,
      messageKind: normalized.messageKind,
    })
  : null;

const debugMsg = Object.assign({}, downstreamMsg);

return [downstreamMsg, httpResponse, debugMsg];

const isObj = (value) => value && typeof value === "object" && !Array.isArray(value);
const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim();
  return normalized ? normalized : null;
};

const update = isObj(msg.maxUpdate) ? msg.maxUpdate : null;
if (!update) {
  return null;
}

const apiBase = (() => {
  try {
    return toStr(env.get("SUPPORT_API_BASE_URL"));
  } catch {
    return null;
  }
})();

const baseUrl = apiBase || "http://127.0.0.1:1880";
const query = new URLSearchParams();
query.set("channel", "MAX");
if (update.recipient?.chatId) query.set("chatId", update.recipient.chatId);
if (update.sender?.userId) query.set("channelUserId", update.sender.userId);
if (update.contact?.phone) query.set("phone", update.contact.phone);

msg.method = "GET";
msg.url = `${baseUrl}/lk/support/clients/resolve?${query.toString()}`;
msg.headers = { Accept: "application/json" };
return msg;

const isObj = (value) => value && typeof value === "object" && !Array.isArray(value);
const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim();
  return normalized ? normalized : null;
};
const uniq = (values) => Array.from(new Set(values.filter(Boolean)));

function getApiBase() {
  try {
    return toStr(env.get("SUPPORT_API_BASE_URL")) || "http://127.0.0.1:1880";
  } catch {
    return "http://127.0.0.1:1880";
  }
}

function buildMessage(chatId, content, options = null) {
  return {
    payload: {
      chatId,
      type: "message",
      content,
      options: options || undefined,
    },
  };
}

function buildContactOptions() {
  return {
    reply_markup: JSON.stringify({
      keyboard: [[{ text: "Поделиться номером", request_contact: true }]],
      resize_keyboard: true,
      one_time_keyboard: false,
    }),
  };
}

function buildStationOptions() {
  return {
    reply_markup: JSON.stringify({
      keyboard: [
        [{ text: "Нагатинская" }],
        [{ text: "Нагатинская Премиум" }],
        [{ text: "Терехово" }],
        [{ text: "Сколково" }],
        [{ text: "Ясенево" }],
        [{ text: "Селигерская" }],
        [{ text: "Сочи" }],
        [{ text: "Точка сбора" }],
      ],
      resize_keyboard: true,
      one_time_keyboard: false,
    }),
  };
}

const update = isObj(msg.maxUpdate) ? msg.maxUpdate : null;
if (!update) {
  return [null, null, msg];
}

const clientPayload = isObj(msg.payload) ? msg.payload : {};
const client = isObj(clientPayload.client) ? clientPayload.client : null;
const chatId = toStr(update.recipient?.chatId);
const senderUserId = toStr(update.sender?.userId);
const senderName = toStr(update.sender?.name) || "Клиент";
const authStatus = toStr(client?.authStatus) || (update.contact?.phone ? "AUTHORIZED" : "PENDING_CONTACT");
const workflowState = toStr(client?.workflowState)
  || (authStatus !== "AUTHORIZED" ? "WAIT_CONTACT" : (toStr(client?.lastStationId) ? "READY" : "WAIT_STATION"));
const stationId = update.station?.id || toStr(client?.lastStationId) || "UNASSIGNED";
const stationName = update.station?.name || toStr(client?.lastStationName) || "Без станции";

const supportEvent = {
  channel: "MAX",
  direction: "INBOUND",
  authorType: "CLIENT",
  eventType: "MESSAGE",
  text: update.text,
  displayName: senderName,
  phone: update.contact?.phone || null,
  phoneNumbers: update.contact?.phone ? [update.contact.phone] : [],
  authStatus,
  workflowState,
  stationId,
  stationName,
  channelUserId: senderUserId,
  userId: senderUserId,
  chatId,
  externalMessageId: update.messageId || null,
  externalThreadId: chatId,
  senderName,
  senderId: senderUserId,
  attachments: update.attachments || [],
  metadata: {
    provider: "max",
    messageKind: update.messageKind,
    command: update.command || null,
    stationToken: update.station?.id || null,
  },
};

const outboundMessages = [];

if (update.command === "/start") {
  supportEvent.eventType = "START";
  if (authStatus !== "AUTHORIZED") {
    supportEvent.authStatus = "PENDING_CONTACT";
    supportEvent.workflowState = "WAIT_CONTACT";
    outboundMessages.push(buildMessage(
      chatId,
      "Чтобы подключить администратора, нужно подтвердить номер телефона. Нажмите кнопку ниже.",
      buildContactOptions(),
    ));
  } else if (workflowState === "WAIT_STATION") {
    outboundMessages.push(buildMessage(
      chatId,
      "Номер подтверждён. Теперь выберите станцию, чтобы мы направили диалог нужной команде.",
      buildStationOptions(),
    ));
  } else {
    outboundMessages.push(buildMessage(
      chatId,
      "Вы уже авторизованы. Напишите сообщение, и мы подключим администратора по вашей станции.",
    ));
  }
} else if (update.messageKind === "contact" && update.contact?.phone) {
  supportEvent.eventType = "CONTACT_SHARED";
  supportEvent.phone = update.contact.phone;
  supportEvent.phoneNumbers = [update.contact.phone];
  supportEvent.authStatus = "AUTHORIZED";
  supportEvent.workflowState = stationId && stationId !== "UNASSIGNED" ? "READY" : "WAIT_STATION";
  supportEvent.text = "Клиент поделился контактом";
  outboundMessages.push(buildMessage(
    chatId,
    "Спасибо. Номер сохранён. Теперь выберите станцию, чтобы мы направили обращение нужному администратору.",
    buildStationOptions(),
  ));
} else if (update.messageKind === "station" && update.station) {
  supportEvent.eventType = "STATION_SELECTED";
  supportEvent.stationId = update.station.id;
  supportEvent.stationName = update.station.name;
  supportEvent.text = `Выбрана станция: ${update.station.name}`;
  supportEvent.workflowState = authStatus === "AUTHORIZED" ? "READY" : "WAIT_CONTACT";
  if (authStatus !== "AUTHORIZED") {
    outboundMessages.push(buildMessage(
      chatId,
      "Подключить администратора мы можем только для авторизованных пользователей. Сначала поделитесь номером телефона.",
      buildContactOptions(),
    ));
  } else {
    outboundMessages.push(buildMessage(
      chatId,
      `Станция ${update.station.name} сохранена. Теперь можете написать сообщение для администратора.`,
    ));
  }
} else {
  supportEvent.eventType = "MESSAGE";
  if (authStatus !== "AUTHORIZED") {
    supportEvent.workflowState = "WAIT_CONTACT";
    outboundMessages.push(buildMessage(
      chatId,
      "Подключить администратора мы можем только для авторизованных пользователей. Поделитесь номером телефона, и мы продолжим диалог.",
      buildContactOptions(),
    ));
  } else if (workflowState === "WAIT_STATION") {
    outboundMessages.push(buildMessage(
      chatId,
      "Номер подтверждён, но станция ещё не выбрана. Пожалуйста, выберите станцию.",
      buildStationOptions(),
    ));
  }
}

const supportEventMsg = Object.assign({}, msg, {
  method: "POST",
  url: `${getApiBase()}/lk/support/dialogs/events`,
  headers: { "Content-Type": "application/json", Accept: "application/json" },
  payload: supportEvent,
});

const debugMsg = Object.assign({}, msg, {
  payload: {
    maxUpdate: update,
    supportEvent,
    outboundCount: outboundMessages.length,
    clientFound: Boolean(client),
  },
});

return [supportEventMsg, outboundMessages, debugMsg];
